public class NumArray {
    int[] nums;

    NumArray(int[] nums) {
        this.nums = nums.clone();
    }

    void update(int index, int val) {
        nums[index] = val;                        // O(1) update
    }

    int sumRange(int left, int right) {
        int sum = 0;
        for (int i = left; i <= right; i++) sum += nums[i];  // re-sum the whole range every time
        return sum;
    }
}

