class NumArray:
    def __init__(self, nums):
        self.n = len(nums)
        self.nums = list(nums)
        self.bit = [0] * (self.n + 1)
        for i, v in enumerate(nums):
            self._add(i, v)

    def _add(self, i, delta):
        i += 1
        while i <= self.n:
            self.bit[i] += delta
            i += i & (-i)

    def _prefix(self, i):
        i += 1
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & (-i)
        return s

    def update(self, index, val):
        delta = val - self.nums[index]         # adjust the tree by just the change
        self.nums[index] = val
        self._add(index, delta)

    def sum_range(self, left, right):
        return self._prefix(right) - (self._prefix(left - 1) if left > 0 else 0)

